-- Lima 2027 · Distribution and reception parameters, from the WBM I presentation (21 Nov 2026, "Distribución internacional").
insert into public.distribution_channels (kind, position, title_es, title_en, title_pt, body_es, body_en, body_pt, visibility, status, published_at, content_updated_at)
select * from (values
 ('satellite', 1, 'Satélite · 6 canales', 'Satellite · 6 channels', 'Satélite · 6 canais',
  '<ul><li><strong>Canales:</strong> 6, incluido el Canal Integrado 24/7</li><li><strong>Formato:</strong> HD 1080i 59.94 · SDR · 16:9</li><li><strong>Vídeo:</strong> H.265 (HEVC)</li><li><strong>Modulación:</strong> DVB-S2 8PSK · FEC 5/6</li><li><strong>Symbol rate:</strong> 28.500</li><li><strong>Audio:</strong> 48 kHz · MPEG-1 Layer 2</li><li><strong>Satélite y banda:</strong> [POR CONFIRMAR]</li></ul>',
  '<ul><li><strong>Channels:</strong> 6, including the 24/7 Integrated Channel</li><li><strong>Format:</strong> HD 1080i 59.94 · SDR · 16:9</li><li><strong>Video:</strong> H.265 (HEVC)</li><li><strong>Modulation:</strong> DVB-S2 8PSK · FEC 5/6</li><li><strong>Symbol rate:</strong> 28,500</li><li><strong>Audio:</strong> 48 kHz · MPEG-1 Layer 2</li><li><strong>Satellite and band:</strong> [TBC]</li></ul>',
  '<ul><li><strong>Canais:</strong> 6, incluindo o Canal Integrado 24/7</li><li><strong>Formato:</strong> HD 1080i 59.94 · SDR · 16:9</li><li><strong>Vídeo:</strong> H.265 (HEVC)</li><li><strong>Modulação:</strong> DVB-S2 8PSK · FEC 5/6</li><li><strong>Symbol rate:</strong> 28.500</li><li><strong>Áudio:</strong> 48 kHz · MPEG-1 Layer 2</li><li><strong>Satélite e banda:</strong> [A CONFIRMAR]</li></ul>'),
 ('srt', 2, 'SRT · 13 señales dedicadas', 'SRT · 13 dedicated signals', 'SRT · 13 sinais dedicados',
  '<ul><li><strong>Señales:</strong> 13 señales dedicadas</li><li><strong>Transporte:</strong> IP · SRT caller / listener</li><li><strong>Vídeo:</strong> H.264</li><li><strong>Bitrate:</strong> 20 Mbps por señal</li><li><strong>Cifrado:</strong> AES-128 / AES-256</li><li><strong>Identificación:</strong> Stream ID por señal (ver la parrilla de señales)</li></ul>',
  '<ul><li><strong>Signals:</strong> 13 dedicated signals</li><li><strong>Transport:</strong> IP · SRT caller / listener</li><li><strong>Video:</strong> H.264</li><li><strong>Bitrate:</strong> 20 Mbps per signal</li><li><strong>Encryption:</strong> AES-128 / AES-256</li><li><strong>Identification:</strong> one Stream ID per signal (see the feed grid)</li></ul>',
  '<ul><li><strong>Sinais:</strong> 13 sinais dedicados</li><li><strong>Transporte:</strong> IP · SRT caller / listener</li><li><strong>Vídeo:</strong> H.264</li><li><strong>Bitrate:</strong> 20 Mbps por sinal</li><li><strong>Criptografia:</strong> AES-128 / AES-256</li><li><strong>Identificação:</strong> um Stream ID por sinal (ver a grade de sinais)</li></ul>'),
 ('other', 3, 'Pruebas técnicas', 'Technical tests', 'Testes técnicos',
  '<ul><li><strong>T–15 días:</strong> primera prueba de satélite y SRT</li><li><strong>T–7 días:</strong> segunda prueba de satélite y SRT</li><li><strong>Día 1:</strong> señales en el aire</li></ul><p>Fechas, horarios y parámetros exactos se comunicarán con antelación a todos los Right Holders.</p>',
  '<ul><li><strong>T–15 days:</strong> first satellite and SRT test</li><li><strong>T–7 days:</strong> second satellite and SRT test</li><li><strong>Day 1:</strong> signals on air</li></ul><p>Exact dates, times and parameters will be sent to all Right Holders in advance.</p>',
  '<ul><li><strong>T–15 dias:</strong> primeiro teste de satélite e SRT</li><li><strong>T–7 dias:</strong> segundo teste de satélite e SRT</li><li><strong>Dia 1:</strong> sinais no ar</li></ul><p>Datas, horários e parâmetros exatos serão comunicados com antecedência a todos os Right Holders.</p>')
) v(kind, position, title_es, title_en, title_pt, body_es, body_en, body_pt)
cross join lateral (select 'all'::public.content_visibility, 'published'::public.publish_status, now(), now()) x(vis, st, pa, cu)
where not exists (select 1 from public.distribution_channels);
